globalCss:
/* Editorial 全局样式 */
:root {
  --ed-bg: #F9F8F6;
  --ed-fg: #1C1C1C;
}

body {
  font-family: ui-sans-serif, system-ui, -apple-system, sans-serif;
  background: var(--ed-bg);
  color: var(--ed-fg);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  font-weight: 400;
  letter-spacing: -0.02em;
}

::selection {
  background: var(--ed-fg);
  color: var(--ed-bg);
}

/* Hover underline animation */
.hover-underline {
  position: relative;
}
.hover-underline::after {
  content: '';
  position: absolute;
  width: 100%;
  transform: scaleX(0);
  height: 1px;
  bottom: 0;
  left: 0;
  background-color: currentColor;
  transform-origin: bottom right;
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}
.hover-underline:hover::after {
  transform: scaleX(1);
  transform-origin: bottom left;
}

/* Clip-path image reveal */
.clip-reveal {
  clip-path: inset(100% 0 0 0);
  transition: clip-path 1.5s cubic-bezier(0.16, 1, 0.3, 1);
}
.clip-reveal.revealed {
  clip-path: inset(0% 0 0 0);
}
@keyframes editorial-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes editorial-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.editorial-gradient {
  background: linear-gradient(135deg, #1C1C1C, #1C1C1C);
}

.editorial-gradient-text {
  background: linear-gradient(135deg, #1C1C1C, #1C1C1C);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.editorial-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(28, 28, 28, 0.08);
}

.editorial-animate-in {
  animation: editorial-fade-in 0.5s ease-out both;
}
